    /// Render selected live apps in their virtual strip coordinates, without
    /// clipping them to the physical output. Used by the compositor's capture
    /// executor for `FullApp` and `WholeStrip`; the normal screen scene remains
    /// the source for visible-region/display captures.
    #[allow(
        clippy::too_many_arguments,
        reason = "capture rendering needs the complete widget paint context"
    )]
    pub fn draw_capture_targets(
        &mut self,
        target_ids: &[String],
        extent: ui::widget::CaptureExtent,
        complete_semantic_content: bool,
        scene: &mut Scene,
        transform: Affine,
        text_renderer: &mut TextRenderer,
        theme: &Theme,
        presence: &PresenceCtx,
    ) -> Vec<Rect> {
        let rows: Vec<_> = self.group_row_ptrs.values().copied().collect();
        let mut rects = Vec::new();
        for row in rows {
            // SAFETY: the pointers reference boxed rows owned by `content`;
            // this exclusive host borrow and sequential traversal prevent
            // aliasing, matching the existing capture-target/read paths.
            unsafe {
                rects.extend((&mut *row).draw_capture_targets(
                    target_ids,
                    extent,
                    complete_semantic_content,
                    scene,
                    transform,
                    text_renderer,
                    theme,
                    presence,
                ));
            }
        }
        rects
    }

    /// Create or refresh a capture-owned presentation surface. Live requests
    /// update only their pixels when the id already exists, preserving the
    /// user's window geometry; pinned requests use unique ids and remain
    /// immutable after insertion.
    pub(crate) fn upsert_capture_surface(&mut self, request: CaptureSurfaceRequest<'_>) {
        let PreparedCaptureSurface {
            id,
            title,
            image,
            pixel_aspect,
            preferred_size,
            spawn_from,
            handoff_layers,
            crossfade_preview,
            document_aspect,
        } = request.prepare();
        if let Some((_, window)) = self
            .capture_mirrors
            .iter_mut()
            .find(|(mirror_id, _)| mirror_id == id)
        {
            window.content_mut().set_image(image);
            return;
        }
        let initial_size = capture_mirror_initial_size(self.rect, pixel_aspect, preferred_size);
        let body_w = initial_size.width;
        let body_h = initial_size.height;
        let visible_spawn = visible_capture_spawn(self.rect, spawn_from);
        let content = match crossfade_preview {
            Some(preview) => CaptureMirrorImage::new_crossfade(image, preview, document_aspect),
            None => CaptureMirrorImage::new(image, handoff_layers),
        };
        let mut window = FloatingWindow::new(title, content)
            .open(true)
            .modal(false)
            .closable(true)
            .overlay_chrome(true)
            .with_initial_size(body_w, body_h)
            .spawn_from(visible_spawn);
        if document_aspect.is_none() {
            window = window.with_aspect_ratio(pixel_aspect);
        }

        let window_size = vello::kurbo::Size::new(
            body_w.max(ui::widget::MIN_WIDTH),
            body_h.max(ui::widget::MIN_HEIGHT),
        );
        let origin = capture_mirror_origin(self.rect, visible_spawn, window_size);
        window.place_at_within(self.rect, origin);
        self.capture_mirrors.push((id.to_string(), window));
        self.capture_mirrors_structure_dirty = true;
    }

    /// Paint capture-owned presentation surfaces as a distinct compositor
    /// pass. Keeping mirrors and status chrome out of the ordinary desktop
    /// scene prevents recursive `PiP` feedback and keeps the recording pill out
    /// of the encoded video.
    pub fn draw_capture_overlays(
        &mut self,
        scene: &mut Scene,
        transform: Affine,
        text_renderer: &mut TextRenderer,
        theme: &Theme,
        presence: &PresenceCtx,
    ) {
        self.capture_studio.set_overlay_rect(self.rect);
        for (_, mirror) in &mut self.capture_mirrors {
            mirror.draw(scene, transform, text_renderer, theme, presence);
        }
        self.capture_studio
            .draw_countdown_indicator(scene, transform, text_renderer, theme);
        self.capture_studio
            .draw_recording_indicator(scene, transform, text_renderer, theme);
        if let Some(markup) = self.screenshot_markup.as_mut() {
            markup.draw(scene, transform, text_renderer, theme, presence);
        }
    }

    pub fn take_closed_capture_mirrors(&mut self) -> Vec<String> {
        std::mem::take(&mut self.closed_capture_mirrors)
    }

    #[cfg(test)]
    pub(crate) fn capture_mirror_count_for_tests(&self) -> usize {
        self.capture_mirrors.len()
    }

    #[allow(
        clippy::too_many_arguments,
        clippy::trivially_copy_pass_by_ref,
        reason = "Widget event-dispatch context plus the selected mirror node"
    )]
    fn route_capture_mirror_event(
        &mut self,
        event: &WindowEvent,
        scale_factor: f64,
        modifiers: &winit::event::Modifiers,
        state: &mut AutoCommit,
        path: &ObjId,
        handled: &mut bool,
        focus_target: &mut Option<NodeId>,
        taffy: &TaffyTree<()>,
    ) -> bool {
        let pointer = self.last_cursor.unwrap_or(Point::ZERO);
        if matches!(event, WindowEvent::CursorMoved { .. }) {
            // Every PiP must observe pointer departure as well as arrival.
            // Routing only to the surface under the new point leaves the old
            // one's hover chrome permanently painted over its pixels.
            for (_, mirror) in &mut self.capture_mirrors {
                if mirror.wants_pointer_capture() {
                    mirror.update_pointer_presence(pointer);
                } else {
                    mirror.update_pointer_position(pointer);
                }
            }
        }
        let Some(index) = self.capture_mirrors.iter().rposition(|(_, mirror)| {
            mirror.wants_pointer_capture()
                || (mirror.is_open() && mirror.window_rect().contains(pointer))
        }) else {
            return false;
        };
        let Some(node) = self.capture_mirror_nodes.get(index).copied() else {
            return false;
        };
        let Some((_, mirror)) = self.capture_mirrors.get_mut(index) else {
            return false;
        };
        mirror.handle_event(
            event,
            scale_factor,
            modifiers,
            state,
            path,
            handled,
            focus_target,
            node,
            taffy,
        );
        let consumed = *handled || mirror.wants_pointer_capture();
        if !mirror.is_open() {
            let (id, _) = self.capture_mirrors.remove(index);
            self.closed_capture_mirrors.push(id);
            self.capture_mirrors_structure_dirty = true;
        }
        consumed
    }

    /// Drained by the compositor's floating-surface host after app updates.
    /// The request keeps the app/region identity intact, so the shell can
    /// continue presenting the source rather than a copied panel.
    pub fn take_floating_surface_requests(
        &mut self,
    ) -> Vec<ui::floating_surface::FloatingSurfaceRequest> {
        std::mem::take(&mut self.pending_floating_surfaces)
    }

    pub fn take_floating_surface_source_updates(&mut self) -> Vec<(String, Rect)> {
        std::mem::take(&mut self.pending_floating_surface_updates)
    }

    pub fn active_floating_surface_ids(&self) -> Vec<String> {
        self.group_row_ptrs
            .values()
            .flat_map(|ptr| {
                // SAFETY: stable Box<GroupRow> contract; this is a shared
                // read and cannot race a workspace reconciliation sweep.
                let row: &GroupRow = unsafe { &**ptr };
                ui::widget::FloatingSurfaceWidgetExt::active_floating_surface_ids(row)
            })
            .collect()
    }

    pub fn on_floating_surface_host_message(
        &mut self,
        message: &ui::floating_surface::FloatingSurfaceHostMessage,
    ) {
        for &ptr in self.group_row_ptrs.values() {
            // SAFETY: same stable Box<GroupRow> contract as the request
            // harvesters; the host owns exclusive access for dispatch.
            let row: &mut GroupRow = unsafe { &mut *ptr };
            ui::widget::FloatingSurfaceWidgetExt::on_floating_surface_host_message(row, message);
        }
    }

    /// Replace the QS action dispatcher. Tests use this to swap in a
    /// recording impl that captures every `set_*` call instead of
    /// shelling out to `nmcli` / `brightnessctl` / `bluetoothctl` /
    /// `wpctl` / `powerprofilesctl`. Production builds keep the
    /// default [`crate::shell::quick_settings::actions::RealQsActions`].
    #[must_use]
    pub fn with_qs_actions(
        mut self,
        actions: Box<dyn crate::shell::quick_settings::actions::QsActions>,
    ) -> Self {
        let actions: std::rc::Rc<dyn crate::shell::quick_settings::actions::QsActions> =
            std::rc::Rc::from(actions);
        self.qs_actions = actions.clone();
        self.qs_action_slot.replace(
            actions,
            crate::shell::quick_settings::actions::QsActionAvailability::all(),
        );
        // Replacing where quick settings writes means this host is not
        // driving the host, so it must not read from it either.
        self.qs_refresh.disable_os_reads();
        self
    }

    /// Supply the durable Quick Settings arrangement explicitly. Production
    /// uses the persisted per-user configuration; embedders and interaction
    /// tests can inject a deterministic arrangement without reading or
    /// rewriting the desktop user's settings file.
    #[must_use]
    pub fn with_quick_settings_config(
        mut self,
        config: settings_store::hardware::QuickSettingsConfig,
    ) -> Self {
        self.qs_root = QuickSettingsRoot::with_config(config);
        self
    }

    /// Install the live-status bridge. Only the compositor's real-session
    /// constructors do this; without it the tray's readings stay `None`
    /// and it draws no indicators, which is what keeps golden renders
    /// identical across machines.
    #[must_use]
    pub fn with_status_bridge(mut self, bridge: crate::shell::status::StatusBridge) -> Self {
        self.status_bridge = Some(bridge);
        // A spawn failure means resource exhaustion on the host; the session
        // still runs, just without persistent audio-balance/mono transforms.
        self.session_audio_policy =
            match crate::shell::session_audio_policy::SessionAudioPolicyOwner::spawn() {
                Ok(owner) => Some(owner),
                Err(error) => {
                    tracing::warn!(
                        target: "tilo::audio_policy",
                        %error,
                        "failed to spawn the session audio policy worker"
                    );
                    None
                }
            };
        self
    }

    /// The QS action dispatcher, for callers that actuate hardware
    /// outside the popover — the media keys, which drive the same
    /// volume and brightness the sliders do and must go through the same
    /// dispatcher so a test can record them.
    pub fn qs_actions(&self) -> &dyn crate::shell::quick_settings::actions::QsActions {
        self.qs_actions.as_ref()
    }

    /// Handle on the status bridge, for the paths that publish a reading
    /// rather than consume one (the volume keys, which must move the
    /// indicator in the frame they were pressed rather than up to a poll
    /// interval later).
    pub fn status_bridge(&self) -> Option<&crate::shell::status::StatusBridge> {
        self.status_bridge.as_ref()
    }

    /// Paint the transient hardware-key readout, if one is up.
    fn draw_osd(
        &self,
        scene: &mut Scene,
        transform: Affine,
        text_renderer: &mut TextRenderer,
        theme: &Theme,
    ) {
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let now = Instant::now();
        // Expiring here rather than on a timer ties the slab's lifetime
        // to frames that actually paint it, not an idle compositor.
        {
            let mut st = chrome.borrow_mut();
            st.expire_osd(now);
        }
        let Some(osd) = chrome.borrow().osd else {
            return;
        };
        let alpha = osd.alpha_at(now);
        if alpha <= 0.0 {
            return;
        }

        osd.draw(scene, transform, text_renderer, theme, self.rect, alpha);
    }

    /// Copy the poller's latest reading onto the chrome, bumping the
    /// repaint-triggering revision only when it actually changed.
    fn sync_status_from_bridge(&self) {
        let Some(bridge) = self.status_bridge.as_ref() else {
            return;
        };
        let next = bridge.snapshot();
        let Some(chrome) = self.chrome.clone() else {
            return;
        };
        let mut st = chrome.borrow_mut();
        if st.status != next {
            st.status = next;
            st.bump();
        }
    }

    /// Advance the overview crossfade toward `overview_target`, latching a
    /// new transition if the target changed. Returns *linear* progress —
    /// the draw path splits it into its own two-phase, smoothstep-eased
    /// animation, so this must stay linear.
    fn tick_overview_transition(&mut self, target: f32, reduce_motion: bool) -> f32 {
        if reduce_motion {
            let changed = (target - self.overview_target).abs() > f32::EPSILON;
            self.overview_target = target;
            self.overview_t = target;
            self.transition_from = target;
            self.transition_started = None;
            if changed {
                self.overview_selection = if target > 0.5 {
                    self.overview_here_index()
                } else {
                    None
                };
                self.overview_scroll_y = 0.0;
            }
            return target;
        }
        if (target - self.overview_target).abs() > f32::EPSILON {
            self.transition_from = self.overview_t;
            self.overview_target = target;
            self.transition_started = Some(Instant::now());
            // Reseed from the current room so the first arrow press moves
            // one step from here, not from a stale previous visit.
            self.overview_selection = if target > 0.5 {
                self.overview_here_index()
            } else {
                None
            };
            self.overview_scroll_y = 0.0;
        }
        if let Some(started) = self.transition_started {
            let elapsed = millis_to_f32_lossy(started.elapsed().as_millis());
            let duration = millis_to_f32_lossy(u128::from(OVERVIEW_TRANSITION_MS));
            if elapsed >= duration {
                self.overview_t = self.overview_target;
                self.transition_started = None;
            } else {
                let p = (elapsed / duration).clamp(0.0, 1.0);
                // Linear progress; `overview_panel_curve` does the
                // easing, so the shape of the motion lives in one place.
                self.overview_t =
                    self.transition_from + (self.overview_target - self.transition_from) * p;
            }
        }
        self.overview_t
    }

    #[must_use]
    pub fn with_chrome(mut self, chrome: Chrome) -> Self {
        // Mount the notification stack once we have a chrome handle to
        // read from. The widget paints into the viewport's top-right
        // corner each frame via `set_viewport`; it doesn't participate
        // in Taffy because its position is purely absolute.
        self.notification_stack = Some(NotificationStack::new(chrome.clone()));
        chrome.borrow_mut().peer_sync_enabled = self.peer_sync_enabled;
        self.chrome = Some(chrome);
        self
    }

    /// Configure peer-sync palette commands during host construction.
    #[must_use]
    pub fn with_peer_sync_enabled(mut self, enabled: bool) -> Self {
        self.set_peer_sync_enabled(enabled);
        self
    }

    /// Update peer-sync command availability for a live session. This is
    /// needed when trusted first-login provisioning releases the desktop and
    /// starts its transport without a restart.
    pub fn set_peer_sync_enabled(&mut self, enabled: bool) {
        // `ActionsProvider` reads the flag off chrome, not this struct.
        self.peer_sync_enabled = enabled;
        if let Some(chrome) = self.chrome.as_ref() {
            chrome.borrow_mut().peer_sync_enabled = enabled;
        }
    }

