    /// Recording mock content for the host's `content` slot. The palette
    /// test never reaches `content.handle_event`, but the WS-settings click
    /// test needs a layout target so taffy can place the modal.
    struct StubContent {
        rect: Rect,
    }

    impl StubContent {
        fn new() -> Self {
            Self { rect: Rect::ZERO }
        }
    }

    impl Widget for StubContent {
        fn sync(&mut self, _s: &mut AutoCommit, _p: &ObjId) {}

        fn build_layout(
            &mut self,
            taffy: &mut TaffyTree<()>,
            _theme: &Theme,
            node_map: &mut StdHashMap<NodeId, *mut dyn Widget>,
        ) -> NodeId {
            let style = Style {
                size: Size {
                    width: Dimension::percent(1.0),
                    height: Dimension::percent(1.0),
                },
                ..Default::default()
            };
            let node = taffy.new_leaf(style).unwrap();
            node_map.insert(node, std::ptr::from_mut::<dyn Widget>(self));
            node
        }

        fn apply_layout(&mut self, taffy: &TaffyTree<()>, node: NodeId, origin: Point) {
            let l = taffy.layout(node).unwrap();
            self.rect = Rect::new(
                origin.x + f64::from(l.location.x),
                origin.y + f64::from(l.location.y),
                origin.x + f64::from(l.location.x) + f64::from(l.size.width),
                origin.y + f64::from(l.location.y) + f64::from(l.size.height),
            );
        }

        fn draw(
            &mut self,
            _scene: &mut Scene,
            _transform: Affine,
            _text_renderer: &mut TextRenderer,
            _theme: &Theme,
            _presence: &PresenceCtx,
        ) {
        }

        fn handle_event(
            &mut self,
            _event: &WindowEvent,
            _scale_factor: f64,
            _modifiers: &winit::event::Modifiers,
            _state: &mut AutoCommit,
            _path: &ObjId,
            _handled: &mut bool,
            _focus_target: &mut Option<NodeId>,
            _node_id: NodeId,
            _taffy: &TaffyTree<()>,
        ) {
        }

        fn name(&self) -> &'static str {
            "StubContent"
        }

        fn get_rect(&self) -> Rect {
            self.rect
        }
    }

